import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from '../test-utils'
import { gunzipSync } from 'zlib'

/**
 * Test suite for WaitForADuration flow logic bidirectionality
 */
describe('WaitForADuration Bi-Directionality Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    test('Simple WaitForADuration: Fluent to XML and back', async () => {
        const project = ctx.createProject()

        // === FLUENT TO XML ===
        const merged = await getMergedRecordUpdates(project, 'wait-for-duration-simple.now.ts', 'flow-logics/fluent')

        // Verify flow logic instance was created with correct values
        const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
        expect(flowLogicInstances).toBeDefined()

        const waitInstance = flowLogicInstances.find(
            (instance: { logic_definition: string }) => instance.logic_definition === 'fdb2541473031300b61e66476bf6a70e'
        )
        expect(waitInstance).toBeDefined()

        const valuesJson = JSON.parse(gunzipSync(Buffer.from(waitInstance.values, 'base64')).toString('utf8'))
        expect(valuesJson.inputs.find((i: { name: string }) => i.name === 'duration_type').value).toBe(
            'explicit_duration'
        )
        expect(valuesJson.inputs.find((i: { name: string }) => i.name === 'timer_duration').value).toBe(
            '1970-01-01 00:00:05'
        )

        // Verify datapills in log action reference wait outputs
        const actionInstances = merged['sys_hub_action_instance_v2']
        const actionInputs = unzipInputArray(actionInstances[0].values)
        const logMessageInput = findInput(actionInputs, 'log_message')
        expect(logMessageInput.value).toContain('.total_duration')
        expect(logMessageInput.value).toContain('.scheduled_end_date_time')

        // === XML TO FLUENT ===
        const fileContent = loadTestFile('wait-for-duration-simple.now.ts', 'flow-logics/fluent')
        project.addFile({ path: 'wait-for-duration-simple.now.ts', content: fileContent })
        const output = await project.getFile('wait-for-duration-simple.now.ts')?.getOutput()

        const flowXml = output.find((f) => f.path.includes('sys_hub_flow'))
        expect(flowXml).toBeDefined()

        const { changedFiles } = await project.transform({
            path: flowXml?.path,
            content: flowXml?.content,
        })

        const content = changedFiles[0].getContent()

        // Verify waitForADuration is assigned to a variable with correct params
        expect(content).toMatch(/const\s+\w+\s*=\s*wfa\.flowLogic\.waitForADuration/)
        expect(content).toContain("durationType: 'explicit_duration'")
        expect(content).toContain('duration: Duration({')
        expect(content).toContain('days: 0')
        expect(content).toContain('hours: 0')
        expect(content).toContain('minutes: 0')
        expect(content).toContain('seconds: 5')

        // Verify outputs are transformed to datapill calls
        expect(content).toContain('wfa.dataPill')
        expect(content).toContain('.total_duration')
    })

    test('WaitForADuration with conditionals: Fluent to XML and back', async () => {
        const project = ctx.createProject()

        // === FLUENT TO XML ===
        const merged = await getMergedRecordUpdates(
            project,
            'wait-for-duration-conditional.now.ts',
            'flow-logics/fluent'
        )

        const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
        const waitInstances = flowLogicInstances.filter(
            (instance: { logic_definition: string }) => instance.logic_definition === 'fdb2541473031300b61e66476bf6a70e'
        )

        // Should have 3 wait instances: initial, urgent (in if), normal (in else)
        expect(waitInstances.length).toBe(3)

        // Verify nested waits have parent_ui_id set
        const nestedWaits = waitInstances.filter(
            (instance: { parent_ui_id: string }) => instance.parent_ui_id && instance.parent_ui_id !== ''
        )
        expect(nestedWaits.length).toBe(2)

        // === XML TO FLUENT ===
        const fileContent = loadTestFile('wait-for-duration-conditional.now.ts', 'flow-logics/fluent')
        project.addFile({ path: 'wait-for-duration-conditional.now.ts', content: fileContent })
        const output = await project.getFile('wait-for-duration-conditional.now.ts')!.getOutput()

        const flowXml = output.find((f) => f.path.includes('sys_hub_flow'))
        const { changedFiles } = await project.transform({
            path: flowXml!.path,
            content: flowXml!.content,
        })

        const content = changedFiles[0].getContent()

        // Verify if/else structure and multiple waitForADuration calls
        expect(content).toContain('wfa.flowLogic.if')
        expect(content).toContain('wfa.flowLogic.else')
        expect(content.match(/wfa\.flowLogic\.waitForADuration/g)?.length).toBe(3)
        expect(content).toContain('.total_duration')
    })

    test('WaitForADuration and Action without datapills: uuid should be cleaned up during transform', async () => {
        const project = ctx.createProject()

        // === FLUENT TO XML ===
        const merged = await getMergedRecordUpdates(project, 'uuid-cleanup-no-datapills.now.ts', 'flow-logics/fluent')

        // Verify flow logic instance was created (WaitForADuration)
        const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
        expect(flowLogicInstances).toBeDefined()

        const waitInstance = flowLogicInstances.find(
            (instance: { logic_definition: string }) => instance.logic_definition === 'fdb2541473031300b61e66476bf6a70e'
        )
        expect(waitInstance).toBeDefined()
        expect(waitInstance.ui_id).toBeDefined()

        // Verify action instance was created
        const actionInstances = merged['sys_hub_action_instance_v2']
        expect(actionInstances).toBeDefined()
        expect(actionInstances.length).toBe(1)
        expect(actionInstances[0].ui_id).toBeDefined()

        // === XML TO FLUENT ===
        const fileContent = loadTestFile('uuid-cleanup-no-datapills.now.ts', 'flow-logics/fluent')
        project.addFile({ path: 'uuid-cleanup-no-datapills.now.ts', content: fileContent })
        const output = await project.getFile('uuid-cleanup-no-datapills.now.ts')!.getOutput()

        const flowXml = output.find((f) => f.path.includes('sys_hub_flow'))
        expect(flowXml).toBeDefined()

        const { changedFiles } = await project.transform({
            path: flowXml!.path,
            content: flowXml!.content,
        })

        const content = changedFiles[0].getContent()

        // Verify waitForADuration exists with correct params
        expect(content).toContain('wfa.flowLogic.waitForADuration')
        expect(content).toContain("durationType: 'explicit_duration'")
        expect(content).toContain('duration: Duration({')
        expect(content).toContain('seconds: 5')

        // Verify action exists with correct params
        expect(content).toContain('wfa.action')
        expect(content).toContain('action.core.log')
        expect(content).toContain("log_level: 'info'")
        expect(content).toContain('This is a static log message with no datapills')

        // Verify uuid is NOT present in the transformed output
        // The cleanup should remove it even when no datapill transformations occur
        expect(content).not.toMatch(/uuid:\s*['"]/)
    })

    test('Direct XML transform: uuid cleanup based on sys_id match', async () => {
        const project = ctx.createProject()

        // Read the XML file directly (contains action instances with different ui_id/sys_id relationships)
        const xmlPath = path.resolve(__dirname, 'create/DEF0786355_sys_hub_flow_8bd27964e0f24fc88833b0f37cd2e04d.xml')
        const xmlContent = loadTestFile('DEF0786355_sys_hub_flow_8bd27964e0f24fc88833b0f37cd2e04d.xml', 'create')

        const { changedFiles } = await project.transform({
            path: xmlPath,
            content: xmlContent,
        })

        const content = changedFiles[0].getContent()

        // Verify basic structure
        expect(content).toContain('wfa.action')
        expect(content).toContain('action.core.log')

        // Verify action with matching uuid/sys_id does NOT have uuid in output
        expect(content).toContain("$id: Now.ID['3fd6fd50860d47949ad7c3f705d5841c']")

        // Verify action with non-matching uuid/sys_id DOES have uuid preserved
        expect(content).toContain("uuid: 'b8853e67-8a5c-4422-92f2-4534b19c2547'")
    })

    test('Direct XML transform: Duration with 10 hours should render as Duration() format', async () => {
        const project = ctx.createProject()

        // Use the XML file that contains both trigger repeat and waitForADuration with durations
        const xmlPath = path.resolve(__dirname, '../flow-logics/xmls/Test-Duration-With-Repeat-Trigger.xml')
        const xmlContent = loadTestFile('Test-Duration-With-Repeat-Trigger.xml', 'flow-logics/xmls')

        const { changedFiles } = await project.transform({
            path: xmlPath,
            content: xmlContent,
        })

        const content = changedFiles[0].getContent()

        // Verify trigger repeat input uses Duration() format
        expect(content).toContain('trigger.scheduled.repeat')
        expect(content).toContain('repeat: Duration({')
        expect(content).toContain('days: 10')
        expect(content).toContain('hours: 9')
        expect(content).toContain('seconds: 1')

        // Verify waitForADuration also uses Duration() format (not string!)
        expect(content).toContain('wfa.flowLogic.waitForADuration')
        expect(content).toContain("durationType: 'explicit_duration'")
        expect(content).toContain('duration: Duration({')
        expect(content).toContain('hours: 10')

        // Verify it does NOT use string format (the bug we fixed)
        expect(content).not.toContain("duration: '1970-01-01")
    })
})
